input.command:
set -e; T=$(mktemp -d); mkdir -p $T/stubs/caruca/ir $T/stubs/pash_annotations/annotation_generation/annotation_generators $T/stubs/pash_annotations/annotation_generation/datatypes/parallelizability
S=$T/stubs
touch $S/caruca/__init__.py $S/caruca/ir/__init__.py
cat > $S/caruca/ir/syntax.py <<'EOF'
import enum
class Arity(enum.Enum):
    OPTIONAL=1; ZERO_OR_ONE=1; EXACTLY_ONE=2; EXACTLY_TWO=3; ZERO_OR_MORE=4; AT_LEAST_ONE=5; ONE_OR_MORE=5
SyntaxSpecification=list
class Flag:
    def __init__(self, flag, alias=()): self.flag=flag; self.alias=list(alias)
class _V:
    def __init__(self, flag=None, alias=(), flag_followed_by_equals=False, choices=None, arity=Arity.OPTIONAL, dash_as_stdin=False, **kw):
        self.flag=flag; self.alias=list(alias); self.arity=arity; self.dash_as_stdin=dash_as_stdin; self.choices=choices
class Path(_V): pass
for n in "Integer Int Number Pid Duration String Other User Format Selection List Regex Glob Separator Delimiter Char Range Size Permission OwnerGroup Group Signal Variable Command Hostname Filesystem Date DateTime DateFormat TimeStyle Expression PrintfFormat SprintfFormat Geometry SecurityContext SecurityRange SecurityRole SecurityType".split():
    globals()[n]=type(n,(_V,),{})
EOF
P=$S/pash_annotations; for d in $P $P/annotation_generation $P/annotation_generation/annotation_generators $P/annotation_generation/datatypes $P/annotation_generation/datatypes/parallelizability; do touch $d/__init__.py; done
cat > $P/annotation_generation/annotation_generators/InputOutputInfoGenerator_Interface.py <<'EOF'
class InputOutputInfoGeneratorInterface:
    def __init__(self, flags, operands): self.flags=flags; self.operands=operands; self.log=[]
    def does_flag_option_list_contain_at_least_one_of(self, l): return any(f in self.flags for f in l)
    def get_operand_list_length(self): return len(self.operands)
    def __getattr__(self, name):
        if name.startswith(('set_','all_','if_','only_')):
            return lambda *a: self.log.append(name)
        raise AttributeError(name)
EOF
cat > $P/annotation_generation/annotation_generators/ParallelizabilityInfoGenerator_Interface.py <<'EOF'
class ParallelizabilityInfoGeneratorInterface:
    def __init__(self, flags, operands): self.flags=flags; self.operands=operands; self.plist=[]
    def does_flag_option_list_contain_at_least_one_of(self, l): return any(f in self.flags for f in l)
    def append_to_parallelizer_list(self, p): self.plist.append(p)
    def set_commutative(self): self.plist.append("COMMUTATIVE")
    def __getattr__(self, name):
        if name.startswith('append_to_parallelizer_list_'):
            return lambda *a: self.plist.append(name[len('append_to_parallelizer_list_'):])
        raise AttributeError(name)
EOF
cat > $P/annotation_generation/datatypes/parallelizability/Parallelizer.py <<'EOF'
import enum
class AdditionalInfoSplitterToMapper(enum.Enum):
    NO_ADD_INPUT=0; LINE_NUM_OFFSET=1; BYTE_OFFSET=2; LINE_NUM_AND_BYTE_OFFSET=3
def _mk(kind):
    def f(mapper_spec=None, aggregator_spec=None, info_splitter_mapper=None):
        return (kind, mapper_spec, aggregator_spec, info_splitter_mapper)
    return f
make_parallelizer_consec_chunks=_mk("cc"); make_parallelizer_round_robin=_mk("rr"); make_parallelizer_indiv_files=_mk("if")
EOF
cat > $P/annotation_generation/datatypes/parallelizability/MapperSpec.py <<'EOF'
def make_mapper_spec_custom(name, is_implemented=False): return ("mapper", name, is_implemented)
EOF
cat > $P/annotation_generation/datatypes/parallelizability/AggregatorSpec.py <<'EOF'
def make_aggregator_spec_adj_lines_func_from_string_representation(cmd_inv_as_str, is_implemented=False): return ("adjf", cmd_inv_as_str)
def make_aggregator_spec_custom_2_ary_from_string_representation(cmd_inv_as_str, is_implemented=False): return ("2ary", cmd_inv_as_str)
EOF
cd /home/tirandagan.guest/naive-arm
PYTHONPATH=$S:output:output/annotation python3 -I -c '
import json, subprocess, re
from cat import cat_syntax_spec
from caruca.ir.syntax import Flag, Path, Arity
spec_flags=set(); syntax=cat_syntax_spec[0]
for n in syntax[0]:
    assert isinstance(n, Flag), n
    spec_flags.add(n.flag); spec_flags.update(n.alias)
pos=syntax[1][0]; assert isinstance(pos, Path) and pos.arity==Arity.ZERO_OR_MORE and pos.dash_as_stdin
helptxt=subprocess.run(["/usr/bin/cat","--help"],capture_output=True,text=True).stdout
help_flags=set(re.findall(r"(?<![\w-])(--?[A-Za-z][\w-]*)", helptxt.split("Examples")[0]))
help_flags.discard("-vET"); help_flags.discard("-vE"); help_flags.discard("-vT"); help_flags.discard("-n")  # text mentions, -n is an actual option though
help_flags.add("-n")
print("spec == --help flags:", spec_flags==help_flags, spec_flags^help_flags)
for f in sorted(spec_flags):
    r=subprocess.run(["/usr/bin/cat",f,"/dev/null"],capture_output=True)
    assert r.returncode==0, f
print("all spec flags accepted by binary")
j=json.load(open("output/annotation/cat.json"))
json_flags={s for e in j["flag"] for s in (e if isinstance(e,list) else [e])}
print("json == spec:", json_flags==spec_flags, "options:", j["option"])
from InputOutputInfoGeneratorCat import InputOutputInfoGeneratorCat as IO
from ParallelizabilityInfoGeneratorCat import ParallelizabilityInfoGeneratorCat as PA
for flags in [[],["-n"],["-b","-n"],["-s"],["-n","-s"],["-A"],["-E","-T","-v","-u"]]:
    io=IO(flags,["f"]); io.generate_info(); pa=PA(flags,["f"]); pa.generate_info()
    print(f"{str(flags):28s} io={io.log}\n{'':28s} par={pa.plist}")
'
